insert into public.protocol_templates (id,code,title,purpose,trigger_text,document_id,owner_role,category,status,template_rev,kind,sop_ref,process_owner,policy_refs,indicator_ids) values
('55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,'PR-DUTY-HANDOVER','Duty shift handover','Keep 24/7 operations continuous between shifts.','Every change of duty shift at the Operations Center.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'daily_operations','draft',1,'protocol','SOP HR-05 (MOO Ch.2, Annex 2-K; checklist Annex 2-E, form HR-F04)','CDRRMO Head / division leads (SOP HR-05); handover done by the duty officer on shift',array['RA 10121 Sec. 12(c)','NDRRMC Memo 131 s. 2018']::text[],array['A2.5','B4.3']::text[]),
('f726b603-075b-5232-a798-5054f4d3e64d'::uuid,'PR-WARNING-DISSEM','Warning dissemination','Move a hazard bulletin to every at-risk purok, in a form people understand.','On receipt of a PAGASA, PHIVOLCS or MGB bulletin or advisory that affects Ormoc.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'warning','draft',1,'protocol','SOP 4-02 (MOO Ch.4 v1.1)','CDRRMO Head / warning and public information focal person; decisions stay with the competent official',array['RA 10121 Sec. 12(c)','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['A6.1','A6.2','A6.3','A6.4','B5.6']::text[]),
('fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,'PR-EOC-ACTIVATE','EOC activation (Blue or Red)','Stand up the EOC quickly with the right people and records.','When the EOC is raised to Blue or Red as directed by the City Mayor (Responsible Official), or by the EOC Manager under the approved activation protocol.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-04 (MOO Ch.4 v1.1)','Official designated in the EOC EO authorises; EOC Manager implements',array['NDRRMC Memo 131 s. 2018','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['B1.2','B1.3','B4.1','B4.2']::text[]),
('c79bca15-67f0-538e-9e52-8d969da30076'::uuid,'PR-PDRA','Pre-disaster risk assessment (PDRA)','Decide, from the forecast and local exposure, whether to monitor, act early or request a declaration.','When a forecast hazard may affect Ormoc.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 4-03 (MOO Ch.4 v1.1); SOP GOV-05 when a State of Imminent Disaster is considered','CDRRMO Head; Research and Planning with Operations and Warning coordinate',array['RA 12287 and its IRR (2026)','NDRRMC-OCD Contingency Planning Guidebook (2020)']::text[],array['A8.6','A8.8','B1.2']::text[]),
('5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,'PR-SOID-REQUEST','State of Imminent Disaster: request and declaration','Follow RA 12287, its IRR and SOP GOV-05 from the PDRA to the Mayor''s Executive Order.','When the PDRA classifies the projected impact as severe or its equivalent (including where IRR Rule II Sec. 4 factors support that classification below the thresholds) and there is enough lead time to carry out anticipatory action.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP GOV-05 (MOO Ch.1, Annex 1-E)','CDRRMO Head as CDRRMC secretariat',array['RA 12287 and its IRR (2026), Rules III and IV']::text[],array['A1.8','A4.6','A6.7']::text[]),
('f99e18a5-6514-56f9-8bf6-dc31df80cd6f'::uuid,'PR-SOC-DECLARE','State of Calamity: assessment, declaration and lifting','Follow RA 10121 Sec. 16 and SOP GOV-04: the Sangguniang Panlungsod declares or lifts, on the CDRRMC''s recommendation.','When damage and needs reports indicate that a State of Calamity may be warranted.','e715b34c-ec5f-5f4c-b34c-378225a2156c'::uuid,'cdrrmo_head'::public.app_role,'council','draft',1,'workflow','SOP GOV-04 (MOO Ch.1, Annex 1-D)','CDRRMO Head as CDRRMC secretariat',array['RA 10121 Sec. 16']::text[],array['A1.6']::text[]),
('7bcbdc7d-00f9-516a-a030-e4d89022be09'::uuid,'PR-FLASHFLOOD-EARLY','Flash flood and landslide early action','Act on short-lead hazards that cannot wait for a declaration.','When rainfall or river readings reach the City''s early-action thresholds for the Anilao–Malbasag system or upland barangays.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 4-02 (MOO Ch.4 v1.1, short-lead hazards, sec. 6.3)','CDRRMO Operations and Warning (OpCen duty officer)',array['RA 10121 Sec. 12(c)','RA 12287 IRR (2026) Rule IV']::text[],array['A6.1','A6.2','A8.8']::text[]),
('90cb1850-de66-5a00-a46c-47db38ebdc84'::uuid,'PR-SITREP-CYCLE','SitRep cycle','Produce a verified SitRep on schedule every operational period.','At each scheduled SitRep time during an activation.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_staff'::public.app_role,'reporting','draft',1,'protocol','SOP 4-08 (MOO Ch.4 v1.1)','EOC Planning / situation unit; approval by the official in the reporting route',array['DILG VIII Harmonized Disaster Response Reporting Template and SOP','NDRRMC Memo 131 s. 2018']::text[],array['B5.1','B5.2','B1.5','A10.3']::text[]),
('a37bb249-1b6f-585a-8b12-bc80b742cc63'::uuid,'PR-CDRRMC-MEETING','CDRRMC meeting (secretariat)','Run the Council meeting and keep its records complete.','Quarterly, and whenever the Chair calls a special meeting.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'duty_officer'::public.app_role,'council','draft',1,'workflow','MOO Ch.1 (CDRRMC secretariat)','CDRRMO as CDRRMC secretariat',array['RA 10121 Sec. 11']::text[],array['A1.3','A1.4']::text[]),
('33dfaee2-77a8-5b13-956e-bb805634d0b1'::uuid,'PR-LIFT-REPORT','Lifting and 45-day report','Lift a State of Imminent Disaster correctly and report to OCD on time.','When the hazard occurs or the PDRA shows the projected impacts will not be met.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP GOV-05 (MOO Ch.1, Annex 1-E): lifting and the 45-day report','CDRRMO Head as CDRRMC secretariat',array['RA 12287 and its IRR (2026)']::text[],array['A10.8']::text[]),
('abcc88a5-8f0d-577d-84f7-eef04656abf0'::uuid,'WF-BUDGET-CYCLE','LDRRMF budget cycle (SOPs 6-01 and 6-02: computation to quarterly report)','Compute the LDRRMF on the correct base, plan it through an approved LDRRMFIP, execute it, and report and disclose its use every quarter (Chapter 6, SOPs 6-01 and 6-02).','Each budget call, a supplemental budget or realignment, and the end of every quarter.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-01 and SOP 6-02 (MOO Ch.6 v1.1); formerly MOO Ch.2 sec. 2.16.2 (seeded as SOPs 5-01/5-02 on 12 Nov 2026)','CDRRMO Research and Planning (formulation, reporting); Administration and Training (execution); City Budget Office (computation)',array['RA 10121 Sec. 21','NDRRMC-DBM-DILG JMC 2013-1','RA 12287 IRR (2026) Rule V Sec. 1(b)','COA Circular No. 2012-002','DILG Full Disclosure Policy issuances']::text[],array['A3.5','A4.1','A4.2','A4.4','A4.6','A10.5','B7.5']::text[]),
('bf7c56c0-7c61-596a-bab4-0136aa67927d'::uuid,'WF-CP-ACTIVATION','Contingency plan activation and response clustering','Switch on the clusters and EOC modules the activated contingency plan needs, and stand them down when needs are met (Ch.1 sec. 6.3).','When the EOC goes to Blue or Red for a hazard covered by a contingency plan.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'eoc_manager'::public.app_role,'response_clusters','draft',1,'workflow','MOO Ch.1 sec. 6.3','EOC Manager',array['NDRRMC Memo 131 s. 2018']::text[],array['A8.5','B1.4','B4.4']::text[]),
('41fad6bf-c424-5923-b011-9067cf54de64'::uuid,'WF-EOC-DESIGNATION','EOC designation review (quarterly)','Keep every key EOC position covered by a primary and two alternates (Annex 2-D; IAT B4.2).','Every quarter, and after any staff movement.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'cdrrmo_head'::public.app_role,'workforce','draft',1,'workflow','SOP HR-06 (MOO Ch.2, Annex 2-L; register Annex 2-D)','CDRRMO Head / EOC Manager (SOP HR-06): EOC Manager proposes and maintains; CDRRMO Head approves',array['NDRRMC Memo 131 s. 2018','EOC Capability Assessment Checklist']::text[],array['B4.1','B4.2']::text[]),
('a277ed09-4908-5ad8-a47d-9d583ee2137d'::uuid,'WF-GEO-COP','Geospatial common operating picture (SOP 6-GIS-01)','Keep a consistent, validated map of incidents, affected areas, facilities and resources for the EOC.','Maintained in normal operations; run in full whenever the EOC is activated.','d47f0498-4189-5772-9e6c-fecd708e1cbc'::uuid,'eoc_staff'::public.app_role,'geospatial','draft',1,'workflow','SOP 6-GIS-01 (proposed EOC Module SOP; Library draft)','EOC Planning Section (GIS custodian)',array['NDRRMC Memo 131 s. 2018','RA 10173']::text[],array['A5.6','A5.7','B5.3']::text[]),
('4e10fa52-dda1-5ce8-b699-974ea48663df'::uuid,'WF-SOP3-01','SOP 3-1 Hazard data acquisition, validation and map release','Obtain authoritative, current and fit-for-purpose hazard information and control its use.','A request for risk information or a map; a new or revised product from a source agency.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-1 (MOO Ch.3 v1.0)','CDRRMO Research and Planning (GIS custodian)',array['RA 10121 Sec. 12(c)(3)','DHSUD MC 2025-004']::text[],array['A5.1','A5.6','C1.4']::text[]),
('49df9ce9-eaa5-5907-b3fa-a06882687788'::uuid,'WF-SOP3-02','SOP 3-2 Risk information and geospatial repository maintenance','Maintain a controlled, auditable City risk information base.','A new dataset; quarterly review; after a major event or a source-agency revision.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-2 (MOO Ch.3 v1.0)','CDRRMO Head (designated data custodian)',array['RA 10121 Sec. 12(c)(3) and (5)','RA 10173']::text[],array['A5.4','A5.5','A5.6','A5.7']::text[]),
('c624dc19-e6b9-51fe-bef6-d0ef90298714'::uuid,'WF-SOP3-03','SOP 3-3 City climate and disaster risk assessment','Produce a method-compliant CDRA that supports CLUP and development decisions.','CDRA update with the CLUP/CDP revision; material change in hazard, exposure or climate information; new DHSUD issuance.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-3 (MOO Ch.3 v1.0)','CPDO (CDRA process) with the CDRRMO coordinating DRRM evidence',array['DHSUD MC 2025-004 (Enhanced CDRA)','RA 9729 as amended by RA 10174','RA 10121 Sec. 12(c)(3)']::text[],array['A5.2','A5.3','C1.1','C1.3']::text[]),
('90158e48-f867-57e2-a9da-980f5d20e634'::uuid,'WF-SOP3-04','SOP 3-4 Critical facilities and dependency/failure-chain analysis','Identify critical service dependencies and inform protection and restoration priorities.','Yearly; after a change to a critical asset; before a contingency plan or PSCP update.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-4 (MOO Ch.3 v1.0)','CDRRMO (coordination); asset owners accountable for asset data',array['RA 12287 IRR (2026) Rule I Sec. 5(b),(d)']::text[],array['A5.8']::text[]),
('c4aa5d23-496f-53b2-9a86-60a56971a06d'::uuid,'WF-SOP3-05','SOP 3-5 LDRRMP and DRR/CCA mainstreaming interface','Ensure risk evidence is converted into plans, programmes and budget decisions.','Yearly planning and budget cycle (AIP, LDRRMFIP); LDRRMP review; each investment proposal.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-5 (MOO Ch.3 v1.0)','CDRRMO (LDRRMP); CPDO (development-plan integration)',array['RA 10121 Sec. 2 and 12(c)(6)','RA 7160','RA 9729 as amended by RA 10174','NDRRMC-DBM-DILG JMC 2013-1']::text[],array['A3.1','A3.2','C1.1','C1.2','C1.4']::text[]),
('bf9ab417-2698-5c21-9201-36856ff49f99'::uuid,'WF-SOP3-06','SOP 3-6 Hazard-specific contingency plan development and control','Prepare and maintain tested plans for priority hazard scenarios.','A priority hazard without a current plan; a plan past its validity; after an exercise or event; yearly review.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'contingency_planning','draft',1,'workflow','SOP 3-6 (MOO Ch.3 v1.0)','CDRRMO (coordinating process owner); hazard and sector leads (technical owners)',array['RA 10121 Sec. 12(c)','NDRRMC-OCD Contingency Planning Guidebook (2020)']::text[],array['A3.3','A3.6']::text[]),
('7ff2c261-e05f-5d3a-9699-ff0b584a84c1'::uuid,'WF-SOP3-07','SOP 3-7 Public service continuity planning','Protect essential City functions during disruption.','Mayor''s directive; yearly review; after a disruption or exercise.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'continuity','draft',1,'workflow','SOP 3-7 (MOO Ch.3 v1.0)','City continuity executive (to be designated); department heads for their services',array['NDRRMC-OCD PSCP Guidebook']::text[],array['A3.4','B2.7']::text[]),
('3d22ea60-9da2-50c2-889c-f70876393abf'::uuid,'WF-SOP3-08','SOP 3-8 Barangay DRRM plan review and quality assurance','Maintain a verified, quality-assured city-wide BDRRMP status for the 85 barangays.','Yearly BDRRMP cycle; DILG call for plans; a new plan period.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-8 (MOO Ch.3 v1.0)','BDRRMC/Barangay Development Council (plan owner); CDRRMO (city reviewer)',array['RA 10121 Sec. 12(c)(6)','DILG MC 2025-035 (Listo si KAP)']::text[],array['A3.7']::text[]),
('df644c53-097f-508d-a224-5f5f3277a454'::uuid,'WF-SOP3-09','SOP 3-9 Inclusive risk assessment and ecosystem monitoring interface','Embed inclusion and protective-ecosystem evidence in risk intelligence and preparedness.','Each CDRA or plan update; yearly monitoring.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-9 (MOO Ch.3 v1.0)','CDRRMO (coordination); sector offices and CENRO/DENR (technical owners)',array['RA 9710','RA 7277 as amended','RA 10821','RA 8371','RA 10173','RA 9729 as amended by RA 10174']::text[],array['A5.3','A5.5','A7.6','C3.1','C3.2']::text[]),
('6e6abacf-798b-5262-971a-6b8852c22dcc'::uuid,'PR-WARNING-RECEIPT','SOP 4-01 Official warning receipt, verification and escalation','Authenticate, time-stamp and interpret each official product within its source limits, and escalate it to the right decision-maker.','On receipt of an official warning product or a significant local report.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'warning','draft',1,'protocol','SOP 4-01 (MOO Ch.4 v1.1)','CDRRMO Operations and Warning (OpCen duty officer); escalation to the CDRRMO Head',array['RA 10121 Sec. 12(c)','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['A6.1','B4.3']::text[]),
('1d2564de-8992-55c2-94a7-5c14a0a0f1e4'::uuid,'PR-ICS-INTERFACE','SOP 4-05 Initial incident coordination and EOC–ICS interface','Build a shared operational picture and support the Incident Commander without duplicating field command.','On notification of an incident that needs EOC coordination.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-05 (MOO Ch.4 v1.1)','EOC Manager; the Incident Commander / IMT keeps field command',array['NDRRMC Memo 131 s. 2018','NDRRMC MC No. 4 s. 2012 (ICS)']::text[],array['A8.1','B6.1','B1.4','B1.5']::text[]),
('0edbd70e-0dfb-5863-83a8-dab3be25d250'::uuid,'PR-EVACUATION','SOP 4-06 Evacuation coordination and monitoring','Coordinate an authorised evacuation and monitor it safely, accessibly and accountably. The MOO creates no power to order evacuation.','When an official warning, PDRA or incident report indicates people may need to move.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-06 (MOO Ch.4 v1.1)','Decision: official or body named by law and City issuance; CDRRMO coordinates; CSWDO leads camp management (JMC No. 2 s. 2021)',array['RA 10121 Sec. 12(c)','RA 12076','RA 10821','DSWD-DILG-DOH-DepEd JMC No. 2 s. 2021 (CCCM)']::text[],array['A6.2','A7.4','A7.6','A7.9']::text[]),
('cb839857-6ab2-5c3c-9680-1cb7dcbfd1ed'::uuid,'PR-RESOURCE-REQUEST','SOP 4-07 Resource request coordination and mutual-aid escalation','Move each operational request from receipt to fulfilment or referral, with financial and property controls.','On receipt of a resource or service request during an activation.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-07 (MOO Ch.4 v1.1)','EOC Manager / Logistics; approval and expenditure stay with the competent offices (Chapter 5)',array['RA 10121 Sec. 21','RA 12009 and its IRR']::text[],array['B6.2','A8.3','A7.5']::text[]),
('94f696d5-6a2a-5381-8b5a-afbfc787e786'::uuid,'PR-EOC-DEACTIVATE','SOP 4-09 EOC deactivation, transition and after-action review','Close the activation in a controlled way and hand unresolved work to permanent, recovery and continuity arrangements.','When the incident has stabilised and the Incident Commander recommends termination.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-09 (MOO Ch.4 v1.1)','Deactivation: official designated in the EOC EO; EOC Manager coordinates handover and closeout',array['NDRRMC Memo 131 s. 2018','NDRRMC-OCD Contingency Planning Guidebook (2020)','NEDA Disaster Rehabilitation and Recovery Planning Guide']::text[],array['B1.3','B7.4','A10.6']::text[]),
('a6c1f3c1-ace1-55d7-89f3-44ae64f95e22'::uuid,'WF-SOP6-03','SOP 6-03 Special Trust Fund ledger, ageing and programming','Use every unexpended LDRRMF balance for DRRM within its five-year period, oldest first.','Year-end closing; LDRRMFIP preparation; any STF reallocation request.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-03 (MOO Ch.6 v1.1)','City Accountant (ledger); CDRRMO Research and Planning (programming)',array['RA 10121 Sec. 21','COA Circular No. 2012-002','RA 12287 IRR (2026) Rule V Secs. 1(b) and 3']::text[],array['A4.3','A4.6']::text[]),
('b653cdf1-b886-5c46-bb92-39bd6d122d66'::uuid,'PR-QRF-USE','SOP 6-04 Quick Response Fund use under a State of Calamity','Release the QRF quickly, only for relief and recovery, and only under a State of Calamity declared by the SP.','SP declaration of a State of Calamity covering the City or affected barangays.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'eoc','draft',1,'protocol','SOP 6-04 (MOO Ch.6 v1.1)','CDRRMO Head; EOC Finance/Administration desk. Declaration: SP (SOP GOV-04). Expenditure: City Mayor within the appropriation',array['RA 10121 Secs. 16 and 21','NDRRMC-DBM-DILG JMC 2013-1','COA Circular No. 2012-002']::text[],array['A4.2','A1.6']::text[]),
('4f52ff98-ce0a-56a6-a7e1-1c2effedca46'::uuid,'PR-AA-FUNDS','SOP 6-05 Anticipatory action funding and disbursement under a State of Imminent Disaster','Release AA funds immediately and lawfully once a State of Imminent Disaster is declared, within the 10% ceiling and the tranche rule.','The Mayor''s declaration of a State of Imminent Disaster; a revised impact forecast during the declaration.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 6-05 (MOO Ch.6 v1.1)','CDRRMO Head; EOC Finance/Administration desk. Declaration: City Mayor (SOP GOV-05). Certification and release: Budget, Accounting, Treasury',array['RA 12287 Secs. 6-7','RA 12287 IRR (2026) Rules IV-VI','RA 12009 Sec. 35(b)']::text[],array['A4.6','A10.8','B6.6']::text[]),
('98469129-dd9d-55e9-a8f4-fe9c4c86605c'::uuid,'WF-SOP6-06','SOP 6-06 Pre-arranged supply: supplier list, framework agreements and specifications','Make emergency and AA purchases fast and lawful by agreeing suppliers, items and prices before the event.','Each year before the typhoon season; after an event that exposed a supply gap.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-06 (MOO Ch.6 v1.1)','CDRRMO Administration and Training with CGSO and the BAC Secretariat; award by the HoPE',array['RA 12009 Secs. 16 and 35(b) and IRR','RA 12287 IRR (2026) Rule IV']::text[],array['A4.5','B6.6','B6.3']::text[]),
('ad223db4-da40-5c63-85cc-42ad2f6463d3'::uuid,'PR-EMERGENCY-PROCURE','SOP 6-07 Emergency procurement (negotiated procurement - emergency cases)','Buy what an emergency requires, quickly, with its legal ground on record before the purchase.','An urgent need during a State of Calamity, or where time is of the essence because of a calamity.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 6-07 (MOO Ch.6 v1.1)','EOC Finance/Administration desk and the requesting office; award by the HoPE on BAC recommendation',array['RA 12009 Sec. 35(b) and IRR']::text[],array['A4.5']::text[]),
('0e9ada40-6194-501a-b568-a18fed96ee03'::uuid,'WF-SOP6-08','SOP 6-08 Donations and external assistance: receipt, recording, custody, use and disclosure','Receive donations transparently and use them as the donor and the law intend.','An offer or delivery of cash or in-kind assistance.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-08 (MOO Ch.6 v1.1)','CSWDO (relief goods), CGSO (property), City Treasurer (cash); acceptance by the City Mayor (SP Res. 2024-102); CDRRMO coordinates',array['SP Res. 2024-102','COA Circular No. 2012-002','RA 12287 IRR (2026) Rule V Sec. 2','RA 10173']::text[],array['B6.4']::text[]),
('bd1c123a-8c15-506d-bf2c-75bd4e6713f6'::uuid,'WF-SOP6-09','SOP 6-09 Fund adequacy test and risk financing','Know how far City funds cover a severe credible event, and close the gap with insurance and pre-arranged sources.','Each year before the LDRRMFIP; after a major event or a CDRA update.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-09 (MOO Ch.6 v1.1)','CDRRMO Research and Planning with the City Budget Office, CGSO and CPDO',array['RA 10121 Sec. 21','RA 656','RA 9729 as amended by RA 10174','UNDRR Disaster Resilience Scorecard 3.2.3-3.2.4']::text[],array['A4.9','A4.7','A9.5']::text[]),
('e83a738a-59a7-590a-828a-449c10431eb7'::uuid,'WF-SOP6-10','SOP 6-10 Audit readiness, COA observations and internal control','Prevent common findings and close COA observations on DRRM funds.','Before year-end (pre-audit check); receipt of an AOM or the Annual Audit Report.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-10 (MOO Ch.6 v1.1)','CDRRMO Administration and Training with the City Accountant and the Internal Audit Service where constituted; the City Mayor replies to COA',array['COA Circular No. 2012-002']::text[],array['A4.8']::text[]),
('17ba0741-dad8-5de5-a5fe-9a455f63fc0e'::uuid,'WF-SOP6-12','SOP 6-12 DRRM resource inventory and pre-arranged commitments','Give the EOC one current view of City, barangay, partner and supplier resources and the commitments behind them.','Annual update before the typhoon season; a new agreement or equipment; a call-down test result; after each activation.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 6-12 (MOO Ch.6 v1.1)','CDRRMO Administration and Training (inventory custodian), with the CGSO, BDRRMCs and partners',array['RA 10121','NDRRMC MC No. 4, s. 2012 (ICS resource management)','RA 12287 IRR Rule IV']::text[],array['B6.3','B6.6','A8.3','A10.1']::text[]),
('c2c42630-6b5c-5f5f-9f0d-6ce2016643eb'::uuid,'WF-REC-FRAMEWORK','SOP 5-01 Pre-disaster recovery framework: preparation, adoption and annual update','Have roles, PDNA activation, temporary shelter, debris management, scalable PPAs and recovery fund sources agreed before an event.','Annual planning cycle (aligned with LDRRMP and LDRRMFIP preparation); after an event that triggered a PDNA; after a material plan change.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'recovery','draft',1,'workflow','SOP 5-01 (MOO Ch.5 v1.0)','CDRRMO Head; CDRRMO Research and Planning with CPDO (technical lead)',array['RA 10121','NEDA (2020) Part 2 Sec. I','UNDRR Scorecard Essential 10']::text[],array['A9.5','A3.4']::text[]),
('242f1403-2dcf-5abd-8eca-7c36233ce2aa'::uuid,'PR-PDNA','SOP 5-02 Damage and needs assessment: RDANA to PDNA decision and PDNA conduct','Decide on, carry out and approve a PDNA that gives the program a reliable account of damage, losses and recovery needs.','RDANA shows damage in two or more barangays; a State of Calamity is declared; or national assistance is needed.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'recovery','draft',1,'protocol','SOP 5-02 (MOO Ch.5 v1.0)','CDRRMO Head as PDNA lead; designated PDNA team coordinator',array['RA 10121','NEDA (2020) Part 2 Sec. II.A','OCD PDNA Guidance Notes']::text[],array['A9.1','A8.7']::text[]),
('7b5bb355-f7f8-56ae-8326-50621932967f'::uuid,'WF-SOP7-01','SOP 7-01 LDRRMP monitoring, annual results report and review','Measure the LDRRMP against its indicators each year and give the CDRRMC an evidence-based results report.','Approval of a new or revised LDRRMP (indicator set); each December (data call); each January (report).','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'workflow','SOP 7-01 (MOO Ch.7 v1.0)','CDRRMO Research and Planning (M&E unit), with the CDRRMP Technical Working Group',array['RA 10121 Sec. 11(b)','NDRRMP 2020-2030 RBME Plan','NDRRMC LDRRMP Formulation Guidebook (2022)','NDRRMC Memo No. 147, s. 2017']::text[],array['A10.4']::text[]),
('d539ac8e-ee5c-5ec1-b487-f7a52523d480'::uuid,'PR-AAR','SOP 7-04 After-action review and exercise evaluation','Learn from every significant event and exercise, and turn findings into tracked corrective actions.','Any AAR trigger in Ch.7 sec. 8; the hot wash and ER-F06 from Chapter 4, SOP 4-09.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'protocol','SOP 7-04 (MOO Ch.7 v1.0)','CDRRMO Head, with a designated AAR facilitator',array['RA 10121 Sec. 11(b)','NDRRMC Memo No. 131, s. 2018 (EOC management)','EOC Capability Assessment Checklist']::text[],array['A10.6','B7.4','B7.3']::text[]),
('e777751a-420e-5063-bb3f-e8e435e5cfe3'::uuid,'WF-SOP7-05','SOP 7-05 Corrective and preventive action management (CAPA register)','Track every finding from any source to verified, effective closure (operates GOV-10).','A new finding from any source in Ch.7 Figure 7.2.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'workflow','SOP 7-05 (MOO Ch.7 v1.0)','CDRRMO Research and Planning (register keeper); each accountable owner',array['MOO Ch.1 Sec. 9.5 (GOV-10 CAPA register)','RA 10121 Sec. 11(b)']::text[],array['A10.6','B7.4']::text[]),
('457f40d9-6e3a-5155-9399-e104720cdaa4'::uuid,'WF-SOP7-07','SOP 7-07 Disaster event and loss database maintenance','Keep one standard, sourced record of every disaster that affected the City, for planning, risk assessment and Sendai monitoring.','Final SitRep of an event; completion of RDANA, DROMIC or PDNA; the back-loading plan; each January and July.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'workflow','SOP 7-07 (MOO Ch.7 v1.0)','CDRRMO Research and Planning (M&E unit)',array['RA 10121 Sec. 12(c)','Sendai Framework indicators','DesInventar methodology','RA 10173']::text[],array['A5.4']::text[]),
('04902385-3447-5799-82c5-e6ab891b35b3'::uuid,'WF-SOP7-08','SOP 7-08 Lessons, peer learning and Manual revision','Turn lessons from the City''s own events and from other LGUs and networks into documented changes, including new versions of the Manual.','An approved AAR or IAT result; a peer exchange or network event; a change in law; the annual lessons review each February.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'workflow','SOP 7-08 (MOO Ch.7 v1.0)','CDRRMO Research and Planning (M&E unit); Manual custodian',array['UNDRR Scorecard 6.6.1','MCR2030','RA 10121 Sec. 12(c)']::text[],array['A10.9','A10.6']::text[]),
('69eaf7e9-bfa9-5cbf-a926-419797d44106'::uuid,'WF-SOP7-09','SOP 7-09 Protection of DRRM data: notices, sharing and breach response','Handle personal data in DRRM lawfully and securely, and respond to breaches as the NPC requires.','A new form or data flow; a new data-sharing need; the annual review; a suspected breach.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'cdrrmo_head'::public.app_role,'learning','draft',1,'workflow','SOP 7-09 (MOO Ch.7 v1.0)','City Data Protection Officer, with the CDRRMO privacy compliance officer',array['RA 10173 and its IRR','NPC Circular No. 16-03','NPC Circular No. 2023-06']::text[],array['A5.5']::text[]),
('9e120729-b1bd-590f-8eec-0574cb051e95'::uuid,'WF-SOP8-01','SOP 8-01 Partner register and partnership lifecycle','Bring every DRRM partnership under a written, authorised, registered and reviewed agreement.','A need identified in a contingency plan, AAR or IAT gap; a partner''s offer; an agreement nearing its end; the annual review.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'partnerships','draft',1,'workflow','SOP 8-01 (MOO Ch.8 v1.0)','CDRRMO Administration and Training Division (register keeper)',array['RA 7160 Secs. 22(c), 34-36','RA 10121 Secs. 12(c), 13']::text[],array['A10.2','B6.6']::text[]),
('c67f4eb4-61a3-5904-9854-b0750e2fb454'::uuid,'WF-SOP8-02','SOP 8-02 Inter-LGU technical mutual aid: agreement, activation and demobilisation','Have standing, reciprocal, technical mutual aid with neighbouring LGUs and use it in order when needed.','Agreement: annual plan or a gap found in an AAR. Activation: City capacity exceeded or about to be; a request from a partner LGU.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'partnerships','draft',1,'workflow','SOP 8-02 (MOO Ch.8 v1.0)','CDRRMO Head; EOC Manager',array['RA 7160 Secs. 22(c), 33','RA 10121 Sec. 12(c)','NDRRMC MC No. 4, s. 2012 (ICS)']::text[],array['A10.1','C3.2']::text[]),
('1d7e1646-fc6b-5b21-bbe7-6591c5c00d0a'::uuid,'PR-MUTUAL-AID','SOP 8-02 Mutual aid activation and demobilisation (point of action)','Activate standing mutual aid through the approved route when City capacity is exceeded, and stand it down in order.','City capacity exceeded or about to be; a request received from a partner LGU.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 8-02 (MOO Ch.8 v1.0)','CDRRMO Head; EOC Manager during activation; host Incident Commander directs deployed resources',array['RA 7160 Secs. 22(c), 33','RA 10121 Sec. 12(c)','NDRRMC MC No. 4, s. 2012 (ICS)']::text[],array['A10.1','C3.2']::text[]),
('ab1b76fe-3aae-51e5-b770-721586c6f4e8'::uuid,'PR-AUGMENT-REQUEST','SOP 8-03 Requesting augmentation from the Province, region and national agencies','Request outside help early, through the right route, and absorb it in order.','City and mutual aid resources exceeded or about to be; an agency offers assistance.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 8-03 (MOO Ch.8 v1.0)','EOC Manager, for the CDRRMC Chair; EOC Logistics',array['National Disaster Response Plan','RA 10121','NDRRMC MC No. 4, s. 2012 (ICS)','Regional SOPs']::text[],array['A10.1','A8.5','A10.3']::text[]),
('2b78333d-595b-574f-8d25-9f1a5e72690c'::uuid,'WF-SOP8-04','SOP 8-04 Interface agreements and annual interface review with Part C lead offices','Give every Part C interface an owner, a plan and a yearly review, and report the Interface Index.','Adoption of this chapter; change of a lead office; the annual review before the IAT cycle.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'partnerships','draft',1,'workflow','SOP 8-04 (MOO Ch.8 v1.0)','CDRRMO Research and Planning, with the Part C lead offices',array['IAT v1.7 Part C','RA 12287 IRR Rule IV','UNDRR Scorecard']::text[],array['C1.1','C1.2','C1.3','C1.4','C2.1','C2.2','C2.3','C3.1','C3.2','C3.3','C4.1','C4.2','C4.3','C4.4','C5.1']::text[]),
('9165fb85-6779-5e6a-accc-eddf4b9aa52b'::uuid,'WF-SOP8-05','SOP 8-05 Restoration-priority and continuity arrangements with utilities','Agree before events which facilities are restored first, how utilities and the EOC exchange status, and what backup each will provide.','Annual review before the typhoon season; change in critical facilities; an AAR finding on restoration.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'continuity','draft',1,'workflow','SOP 8-05 (MOO Ch.8 v1.0)','CDRRMO Head; EOC Logistics',array['RA 12287 IRR Rule IV Sec. 4(c)(ii)-(iv)','UNDRR Scorecard Essential 8','RA 10639']::text[],array['C2.1','C2.2']::text[]),
('cffc34d6-3347-5e70-84f5-fcf253237880'::uuid,'WF-SOP8-06','SOP 8-06 Partner seats on the CDRRMC: CSOs, private sector and academe','Keep every partner seat of the CDRRMC filled by an eligible, accredited and active organisation.','Expiry of CSO accreditation; a vacant or inactive seat; a CDRRMC recommendation.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'council','draft',1,'workflow','SOP 8-06 (MOO Ch.8 v1.0)','CDRRMO Head as CDRRMC secretariat, with the SP Secretariat',array['RA 10121 Sec. 11','RA 7160 Secs. 34-36 and DILG rules on CSO accreditation']::text[],array['A1.2','A10.2']::text[]),
('1c08ea27-e4a2-5601-94d0-5255c465d01e'::uuid,'WF-SOP8-07','SOP 8-07 Annual partner forum and pre-season coordination','Meet all partners at least once a year before the typhoon season to confirm roles, contacts and commitments, and to learn from the last season.','Each year before the typhoon season (proposed: April or May).','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'partnerships','draft',1,'workflow','SOP 8-07 (MOO Ch.8 v1.0)','CDRRMO Administration and Training',array['RA 10121 Sec. 12(c)','UNDRR Scorecard 6.1.2, 6.1.4']::text[],array['A10.2','B6.6']::text[]),
('d2b6c5fb-035e-5bd6-843e-54fa705ac8a6'::uuid,'WF-SOP8-08','SOP 8-08 Assistance to other LGUs','Give help to other LGUs through a lawful, documented route that does not weaken the City''s own readiness.','A request from, or a disaster in, another LGU.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'cdrrmo_head'::public.app_role,'partnerships','draft',1,'workflow','SOP 8-08 (MOO Ch.8 v1.0)','CDRRMO Head as CDRRMC secretariat',array['RA 7160 Sec. 33','RA 10121','JMC 2013-1 and the applicable proclamation or rule on LDRRMF use for other LGUs']::text[],array['A10.1']::text[])
